private toggleNewApiDialog() {
  this.newApiOpen = !this.newApiOpen;
  this.newApiDiscovered = null;
  this.newApiDiscoverSelected = [];
  if (this.newApiOpen) {
    this.setMessage("new-api", null);
  }
}

private async discoverNewApiModels() {
  const client = this.gateway.client;
  if (!client || this.newApiDiscovering || this.busy["new-api"]) {
    return;
  }
  const baseUrl = this.newApiBaseUrl.trim();
  if (!/^https?:\/\//.test(baseUrl)) {
    this.setMessage("new-api", {
      kind: "error",
      text: "Base URL 必须以 http:// 或 https:// 开头。",
    });
    return;
  }
  const clientEpoch = this.gateway.epoch;
  this.newApiDiscovering = true;
  this.setMessage("new-api", null);
  try {
    const result = await client.request<ModelsDiscoverResult>("models.discover", {
      baseUrl,
      apiKey: this.newApiKey.trim() || undefined,
    });
    if (!this.gateway.isCurrent({ client, epoch: clientEpoch })) {
      return;
    }
    this.newApiDiscovered = result.models;
    this.newApiDiscoverSelected = result.models;
    if (result.models.length === 0) {
      this.setMessage("new-api", {
        kind: "warning",
        text: `连接成功（${result.latencyMs ?? "?"}ms），但端点未返回任何模型。`,
      });
    } else {
      this.setMessage("new-api", {
        kind: "success",
        text: `连接成功（${result.latencyMs ?? "?"}ms），发现 ${result.models.length} 个模型，已全选。`,
      });
    }
  } catch (error) {
    if (!this.gateway.isCurrent({ client, epoch: clientEpoch })) {
      return;
    }
    this.newApiDiscovered = null;
    this.newApiDiscoverSelected = [];
    this.setMessage("new-api", {
      kind: "error",
      text: `连接失败：${modelProviderErrorMessage(error)}`,
    });
  } finally {
    if (this.gateway.isCurrent({ client, epoch: clientEpoch })) {
      this.newApiDiscovering = false;
    }
  }
}

private applyDiscoveredNewApiModels() {
  const merged = [
    ...parseNewApiModelIds(this.newApiModels),
    ...this.newApiDiscoverSelected,
  ];
  this.newApiModels = [...new Set(merged)].join("\n");
}

private async saveNewApiProvider() {
  const client = this.gateway.client;
  const key = "new-api";
  if (!client || !this.canMutate() || this.busy[key]) {
    return;
  }
  const providerId = this.newApiProviderId.trim().toLowerCase();
  const baseUrl = this.newApiBaseUrl.trim().replace(/\/+$/, "");
  const apiKey = this.newApiKey.trim();
  const modelIds = parseNewApiModelIds(this.newApiModels);
  if (!isValidNewApiProviderId(providerId)) {
    this.setMessage(key, {
      kind: "error",
      text: "提供商 ID 只能包含小写字母、数字和连字符，且必须以字母或数字开头。",
    });
    return;
  }
  if (!/^https?:\/\//.test(baseUrl)) {
    this.setMessage(key, { kind: "error", text: "Base URL 必须以 http:// 或 https:// 开头。" });
    return;
  }
  if (!apiKey) {
    this.setMessage(key, { kind: "error", text: "请填写 API Key。" });
    return;
  }
  if (modelIds.length === 0) {
    this.setMessage(key, { kind: "error", text: "请至少填写一个模型 ID。" });
    return;
  }
  const clientEpoch = this.gateway.epoch;
  const agentEpoch = this.agentEpoch;
  const isCurrent = () =>
    this.gateway.isCurrent({ client, epoch: clientEpoch }) && this.agentEpoch === agentEpoch;
  let failure: ModelProviderRowMessage | null = null;
  await runModelProviderConfigMutation(
    {
      runtimeConfig: this.context.runtimeConfig,
      isCurrentClient: isCurrent,
      isCurrentAgent: isCurrent,
      setBusy: (busy) => this.setBusy(key, busy),
      setMessage: (message) => {
        if (message?.kind === "error") {
          failure = message;
        }
        this.setMessage(key, message);
      },
    },
    {
      raw: {
        models: {
          providers: {
            [providerId]: {
              baseUrl,
              apiKey,
              api: "openai-completions",
              models: modelIds.map((id) => ({ id, name: id })),
            },
          },
        },
      },
      note: `添加自定义 OpenAI 兼容提供商 ${providerId}`,
    },
  );
  if (!isCurrent() || failure) {
    return;
  }
  await this.refresh("replacement");
  if (!isCurrent()) {
    return;
  }
  this.newApiOpen = false;
  this.newApiKey = "";
  this.newApiModels = "";
  this.newApiDiscovered = null;
  this.newApiDiscoverSelected = [];
  this.setMessage(key, null);
  void this.profileActions.probe(providerId, [providerId]);
}

